    14→func init() {
    15→	if env := os.Getenv("E2E_AGENT"); env != "" && env != "roger-roger" {
    16→		return
    17→	}
    18→	// Only register if both binaries exist (roger-roger REPL + protocol handler).
    19→	if _, err := exec.LookPath("roger-roger"); err != nil {
    20→		return
    21→	}
    22→	if _, err := exec.LookPath("entire-agent-roger-roger"); err != nil {
    23→		return
    24→	}
    25→	Register(&RogerRoger{})
    26→}
