     1→// vogon is a deterministic agent binary for E2E canary tests.
     2→// It parses simple prompt instructions, performs file operations, fires
     3→// lifecycle hooks via `entire hooks vogon <verb>`, and writes a minimal
     4→// JSONL transcript. No API calls are made.
     5→//
     6→// Named after the Vogons from The Hitchhiker's Guide to the Galaxy —
     7→// bureaucratic, procedural, and deterministic to a fault.
     8→//
     9→// Usage:
    10→//
    11→//	vogon -p <prompt>   # Headless (single-turn) mode
    12→//	vogon               # Interactive (multi-turn) mode
    13→package main
    14→
    15→import (
    16→	"bufio"
    17→	"bytes"
    18→	"encoding/json"
    19→	"fmt"
    20→	"os"
    21→	"os/exec"
    22→	"path/filepath"
    23→	"regexp"
    24→	"strings"
    25→	"time"
    26→
    27→	"github.com/google/uuid"
    28→)
    29→
    30→func main() {
    31→	prompt := ""
    32→	for i := 1; i < len(os.Args); i++ {
    33→		if os.Args[i] == "-p" && i+1 < len(os.Args) {
    34→			prompt = os.Args[i+1]
    35→			i++
    36→		}
    37→	}
    38→
    39→	dir, err := os.Getwd() //nolint:forbidigo // Standalone binary, not part of CLI — CWD is the repo dir
    40→	if err != nil {
    41→		fatal("getwd: %v", err)
    42→	}
    43→
    44→	sessionID := uuid.New().String()
    45→	transcriptPath := setupTranscript(sessionID)
    46→
    47→	fireHook(dir, "session-start", map[string]string{
    48→		"session_id":      sessionID,
    49→		"transcript_path": transcriptPath,
    50→	})
    51→
    52→	if prompt != "" {
    53→		// Headless mode: single prompt
    54→		runTurn(dir, sessionID, transcriptPath, prompt)
    55→	} else {
    56→		// Interactive mode: read prompts from stdin
    57→		fmt.Fprint(os.Stdout, "> ")
    58→		scanner := bufio.NewScanner(os.Stdin)
    59→		for scanner.Scan() {
    60→			line := strings.TrimSpace(scanner.Text())
    61→			if line == "" || line == "exit" || line == "quit" {
    62→				break
    63→			}
    64→			// Give tmux's Send() time to capture the echoed-input state
    65→			// before we produce any output. Send polls every 200ms; without
    66→			// this pause, vogon output appears in the same capture window
    67→			// as the echo, causing stableAtSend to include final output and
    68→			// preventing WaitFor's contentChanged detection.
    69→			time.Sleep(700 * time.Millisecond)
    70→			fmt.Fprintln(os.Stdout, "Working...")
    71→			runTurn(dir, sessionID, transcriptPath, line)
    72→			fmt.Fprint(os.Stdout, "> ")
    73→		}
    74→	}
    75→
    76→	fireHook(dir, "session-end", map[string]string{
    77→		"session_id":      sessionID,
    78→		"transcript_path": transcriptPath,
    79→	})
    80→}
    81→
    82→func runTurn(dir, sessionID, transcriptPath, prompt string) {
    83→	fireHook(dir, "user-prompt-submit", map[string]any{
    84→		"session_id":      sessionID,
    85→		"transcript_path": transcriptPath,
    86→		"prompt":          prompt,
    87→	})
    88→
    89→	appendTranscript(transcriptPath, "user", prompt)
    90→
    91→	actions := parsePrompt(prompt)
    92→	executeActions(dir, actions)
    93→
    94→	appendTranscript(transcriptPath, "assistant", fmt.Sprintf("Done. Executed %d actions.", len(actions)))
    95→	fmt.Fprintf(os.Stdout, "Done. Executed %d actions.\n", len(actions))
    96→
    97→	fireHook(dir, "stop", map[string]string{
    98→		"session_id":      sessionID,
    99→		"transcript_path": transcriptPath,
   100→	})
   101→}
   102→
   103→// --- Prompt Parsing ---
   104→
   105→type action struct {
   106→	kind    string // "create", "modify", "delete", "commit"
   107→	path    string
   108→	content string
   109→}
   110→
   111→// fileExt is the shared file extension pattern used across all prompt-parsing regexes.
   112→const fileExt = `go|md|txt|js|ts|py|rb|rs|toml|yaml|json`
   113→
   114→var (
   115→	// "create a [single|new|...] [markdown|text] file [at|called] <path>"
   116→	createFileRe = regexp.MustCompile(`(?i)create\s+(?:a\s+)?(?:\w+\s+)*?(?:markdown\s+|text\s+)?file\s+(?:at\s+|called\s+)?([^\s,]+\.(?:` + fileExt + `))`)
   117→	// "create N files: <path> about <topic>, <path> about <topic>"
   118→	createMultiRe = regexp.MustCompile(`(?i)create\s+(?:\w+\s+)*?(?:four|three|two|\d+)\s+(?:\w+\s+)*?(?:markdown\s+)?files?:?\s+(.+)`)
   119→	// "modify <path>"
   120→	modifyFileRe = regexp.MustCompile(`(?i)modify\s+(?:the\s+)?(?:file\s+)?(?:at\s+)?([^\s,]+\.(?:` + fileExt + `))`)
   121→	// "modify [these] N [existing] files[:]"
   122→	modifyMultiRe = regexp.MustCompile(`(?i)modify\s+(?:these\s+)?(?:three|four|two|\d+)\s+(?:\w+\s+)*?files?[.:]\s*(.+)`)
   123→	// "add ... to <path>" (e.g. "add another stanza to poem.txt")
   124→	addToFileRe = regexp.MustCompile(`(?i)add\s+(?:another\s+|a\s+|some\s+)?\w+\s+to\s+([^\s,]+\.(?:` + fileExt + `))`)
   125→	// "delete <path>"
   126→	deleteFileRe = regexp.MustCompile(`(?i)delete\s+(?:the\s+)?(?:file\s+)?(?:at\s+)?([^\s,]+\.(?:` + fileExt + `))`)
   127→	// "commit" anywhere in the prompt, but not "do not commit" / "don't commit"
   128→	commitRe = regexp.MustCompile(`(?i)(?:then\s+|now\s+)?(?:git\s+)?commit\b`)
   129→	// Negative: "do not commit" / "don't commit" with optional object, at sentence boundary
   130→	// Matches: "Do not commit.", "Do not commit the file.", "Do not commit them,"
   131→	// Does NOT match: "Do not commit any other files" (different intent)
   132→	noCommitRe = regexp.MustCompile(`(?i)(?:do\s+not|don'?t)\s+commit(?:\s+(?:it|them|the\s+\w+))?(?:\.|,|$)`)
   133→	// "commit each file separately" — interleave create+commit
   134→	commitSeparatelyRe = regexp.MustCompile(`(?i)commit\s+each\s+file\s+separately`)
   135→	// Individual file in multi-create: "docs/a.md about apples"
   136→	// Topic capture stops at comma, "and", period followed by space+uppercase, or end
   137→	multiFileItemRe = regexp.MustCompile(`([^\s,]+\.(?:` + fileExt + `))\s+(?:about\s+|with\s+|containing\s+)?(.+?)(?:,\s*|\s+and\s+|\.\s+[A-Z]|\.\s*$)`)
   138→	// Individual file in multi-modify: "src/model.go should define ..."
   139→	modifyItemRe = regexp.MustCompile(`([^\s,]+\.(?:` + fileExt + `))\s+should\s+(.+?)(?:,|$)`)
   140→	// "In src/a.go, add ..." pattern for multi-modify
   141→	inFileRe = regexp.MustCompile(`[Ii]n\s+([^\s,]+\.(?:` + fileExt + `))`)
   142→	// Inline content: "with content 'package main; func Foo() {}'"
   143→	inlineContentRe = regexp.MustCompile(`(?i)with\s+content\s+['"]([^'"]+)['"]`)
   144→	// Numbered steps: "(1) ... (2) ... (3) ..."
   145→	numberedStepRe = regexp.MustCompile(`\(\d+\)\s+`)
   146→	// Explicit git command: "Run: git add ... && git commit -m '...'"
   147→	explicitGitRe = regexp.MustCompile(`(?i)run:?\s+git\s+add\s+.+(?:&&\s*git\s+commit|;\s*git\s+commit)`)
   148→	// "about the colour red" → "the colour red"
   149→	topicRe = regexp.MustCompile(`(?i)about\s+(.+?)(?:\.|,|\s+Do\s|\s+do\s|\s+then\s|$)`)
   150→	// Fallback: extract any file path from text
   151→	anyFileRe = regexp.MustCompile(`([^\s,]+\.(?:` + fileExt + `))`)
   152→)
   153→
   154→func parsePrompt(prompt string) []action {
   155→	// Check for numbered-step prompts — parse each step independently to
   156→	// preserve ordering (e.g., create, commit, then create more).
   157→	if numberedStepRe.MatchString(prompt) {
   158→		return parseNumberedSteps(prompt)
   159→	}
   160→	var actions []action
   161→
   162→	// Multi-file modify: "modify these three files: src/model.go should ..., src/view.go should ..."
   163→	// Also matches: "Modify two existing files. In src/a.go, add ..."
   164→	if m := modifyMultiRe.FindStringSubmatch(prompt); m != nil {
   165→		// Try "should" pattern first
   166→		items := modifyItemRe.FindAllStringSubmatch(m[1], -1)
   167→		for _, item := range items {
   168→			actions = append(actions, action{
   169→				kind:    "modify",
   170→				path:    item[1],
   171→				content: "// " + strings.TrimSpace(item[2]) + "\n",
   172→			})
   173→		}
   174→		// Try "In <path>" pattern as fallback
   175→		if len(actions) == 0 {
   176→			for _, item := range inFileRe.FindAllStringSubmatch(m[1], -1) {
   177→				actions = append(actions, action{
   178→					kind:    "modify",
   179→					path:    item[1],
   180→					content: "// Modified by vogon agent\n",
   181→				})
   182→			}
   183→		}
   184→		// Last resort: extract any file paths
   185→		if len(actions) == 0 {
   186→			for _, fm := range anyFileRe.FindAllStringSubmatch(m[1], -1) {
   187→				actions = append(actions, action{
   188→					kind:    "modify",
   189→					path:    fm[1],
   190→					content: "// Modified by vogon agent\n",
   191→				})
   192→			}
   193→		}
   194→	}
   195→
   196→	// Multi-file create: "create four markdown files: docs/a.md about apples, ..."
   197→	if len(actions) == 0 || hasModifyOnly(actions) {
   198→		if m := createMultiRe.FindStringSubmatch(prompt); m != nil {
   199→			items := multiFileItemRe.FindAllStringSubmatch(m[1], -1)
   200→			for _, item := range items {
   201→				actions = append(actions, action{
   202→					kind:    "create",
   203→					path:    item[1],
   204→					content: fmt.Sprintf("# %s\n\nA paragraph about %s.\n", strings.TrimSpace(item[2]), strings.TrimSpace(item[2])),
   205→				})
   206→			}
   207→		}
   208→	}
   209→
   210→	// Single file create — also runs if we only have modifies (combined prompts)
   211→	if !hasCreate(actions) {
   212→		if m := createFileRe.FindStringSubmatch(prompt); m != nil {
   213→			topic := extractTopic(prompt)
   214→			content := fmt.Sprintf("# %s\n\nA paragraph about %s.\n", topic, topic)
   215→			if ic := inlineContentRe.FindStringSubmatch(prompt); ic != nil {
   216→				content = ic[1] + "\n"
   217→			}
   218→			actions = append(actions, action{
   219→				kind:    "create",
   220→				path:    m[1],
   221→				content: content,
   222→			})
   223→		}
   224→	}
   225→
   226→	// Single file modify — also runs if we only have creates (combined prompts)
   227→	if !hasModify(actions) {
   228→		if m := modifyFileRe.FindStringSubmatch(prompt); m != nil {
   229→			actions = append(actions, action{
   230→				kind:    "modify",
   231→				path:    m[1],
   232→				content: "// Modified by vogon agent\n",
   233→			})
   234→		}
   235→	}
   236→
   237→	// "add ... to <path>" as modify (e.g. "add another stanza to poem.txt")
   238→	if !hasModify(actions) {
   239→		if m := addToFileRe.FindStringSubmatch(prompt); m != nil {
   240→			actions = append(actions, action{
   241→				kind:    "modify",
   242→				path:    m[1],
   243→				content: "// Modified by vogon agent\n",
   244→			})
   245→		}
   246→	}
   247→
   248→	// Delete
   249→	if m := deleteFileRe.FindStringSubmatch(prompt); m != nil {
   250→		actions = append(actions, action{kind: "delete", path: m[1]})
   251→	}
   252→
   253→	// Commit: check for "commit each file separately" (interleaved) vs normal.
   254→	// Skip if prompt contains "do not commit" / "don't commit".
   255→	if !noCommitRe.MatchString(prompt) {
   256→		if commitSeparatelyRe.MatchString(prompt) {
   257→			actions = interleaveCommits(actions)
   258→		} else if commitRe.MatchString(prompt) {
   259→			actions = append(actions, action{kind: "commit"})
   260→		}
   261→	}
   262→
   263→	return actions
   264→}
   265→
   266→// parseNumberedSteps splits "(1) ... (2) ... (3) ..." prompts into individual
   267→// steps and parses each one, preserving ordering. This handles prompts like:
   268→// "(1) Create file A. (2) Create file B. (3) git commit. (4) Create file C."
   269→func parseNumberedSteps(prompt string) []action {
   270→	// Split on numbered markers: "(1) ", "(2) ", etc.
   271→	indices := numberedStepRe.FindAllStringIndex(prompt, -1)
   272→	if len(indices) == 0 {
   273→		return nil
   274→	}
   275→
   276→	var steps []string
   277→	for i, idx := range indices {
   278→		start := idx[1] // after the "(N) " marker
   279→		var end int
   280→		if i+1 < len(indices) {
   281→			end = indices[i+1][0]
   282→		} else {
   283→			end = len(prompt)
   284→		}
   285→		step := strings.TrimSpace(prompt[start:end])
   286→		if step != "" {
   287→			steps = append(steps, step)
   288→		}
   289→	}
   290→
   291→	var actions []action
   292→	for _, step := range steps {
   293→		hasExplicitGit := explicitGitRe.MatchString(step)
   294→
   295→		// Create file with optional inline content.
   296→		// Try the full "create ... file ... <path>" regex first, then fall back
   297→		// to "Create <path>" (any file path after a Create verb).
   298→		if m := createFileRe.FindStringSubmatch(step); m != nil {
   299→			content := fmt.Sprintf("# %s\n\nGenerated content.\n", m[1])
   300→			if ic := inlineContentRe.FindStringSubmatch(step); ic != nil {
   301→				content = ic[1] + "\n"
   302→			}
   303→			actions = append(actions, action{kind: "create", path: m[1], content: content})
   304→			if hasExplicitGit {
   305→				actions = append(actions, action{kind: "commit"})
   306→			}
   307→			continue
   308→		}
   309→		if strings.HasPrefix(strings.ToLower(strings.TrimSpace(step)), "create") {
   310→			if m := anyFileRe.FindStringSubmatch(step); m != nil {
   311→				topic := extractTopic(step)
   312→				content := fmt.Sprintf("# %s\n\nA paragraph about %s.\n", topic, topic)
   313→				if ic := inlineContentRe.FindStringSubmatch(step); ic != nil {
   314→					content = ic[1] + "\n"
   315→				}
   316→				actions = append(actions, action{kind: "create", path: m[1], content: content})
   317→				if hasExplicitGit {
   318→					actions = append(actions, action{kind: "commit"})
   319→				}
   320→				continue
   321→			}
   322→		}
   323→
   324→		// Modify file
   325→		if m := modifyFileRe.FindStringSubmatch(step); m != nil {
   326→			actions = append(actions, action{kind: "modify", path: m[1], content: "// Modified by vogon agent\n"})
   327→			if hasExplicitGit {
   328→				actions = append(actions, action{kind: "commit"})
   329→			}
   330→			continue
   331→		}
   332→
   333→		// Delete file
   334→		if m := deleteFileRe.FindStringSubmatch(step); m != nil {
   335→			actions = append(actions, action{kind: "delete", path: m[1]})
   336→			if hasExplicitGit {
   337→				actions = append(actions, action{kind: "commit"})
   338→			}
   339→			continue
   340→		}
   341→
   342→		// Explicit git command without a file operation in this step
   343→		if hasExplicitGit {
   344→			actions = append(actions, action{kind: "commit"})
   345→			continue
   346→		}
   347→
   348→		// Bare commit instruction
   349→		if commitRe.MatchString(step) && !noCommitRe.MatchString(step) {
   350→			actions = append(actions, action{kind: "commit"})
   351→		}
   352→	}
   353→	return actions
   354→}
   355→
   356→func hasCreate(actions []action) bool {
   357→	for _, a := range actions {
   358→		if a.kind == "create" {
   359→			return true
   360→		}
   361→	}
   362→	return false
   363→}
   364→
   365→func hasModify(actions []action) bool {
   366→	for _, a := range actions {
   367→		if a.kind == "modify" {
   368→			return true
   369→		}
   370→	}
   371→	return false
   372→}
   373→
   374→func hasModifyOnly(actions []action) bool {
   375→	if len(actions) == 0 {
   376→		return false
   377→	}
   378→	for _, a := range actions {
   379→		if a.kind != "modify" {
   380→			return false
   381→		}
   382→	}
   383→	return true
   384→}
   385→
   386→// interleaveCommits inserts a commit after each create/modify action.
   387→func interleaveCommits(actions []action) []action {
   388→	var result []action
   389→	for _, a := range actions {
   390→		result = append(result, a)
   391→		if a.kind == "create" || a.kind == "modify" {
   392→			result = append(result, action{kind: "commit"})
   393→		}
   394→	}
   395→	return result
   396→}
   397→
   398→func extractTopic(prompt string) string {
   399→	if m := topicRe.FindStringSubmatch(prompt); m != nil {
   400→		return strings.TrimSpace(m[1])
   401→	}
   402→	return "the topic"
   403→}
   404→
   405→func executeActions(dir string, actions []action) {
   406→	var pendingFiles []string
   407→	for _, a := range actions {
   408→		switch a.kind {
   409→		case "create":
   410→			createFile(dir, a.path, a.content)
   411→			pendingFiles = append(pendingFiles, a.path)
   412→		case "modify":
   413→			modifyFile(dir, a.path, a.content)
   414→			pendingFiles = append(pendingFiles, a.path)
   415→		case "delete":
   416→			deleteFile(dir, a.path)
   417→			pendingFiles = append(pendingFiles, a.path)
   418→		case "commit":
   419→			gitCommit(dir, pendingFiles)
   420→			pendingFiles = nil
   421→		}
   422→	}
