   132→// findSessionsFromShadowTree discovers sessions relevant to a PostCommit by using
   133→// the shadow branch tree as an index. Instead of loading ALL state files and doing
   134→// N ref lookups (O(N) in total session count), this:
   135→//
   136→//  1. Computes the shadow branch name from parentCommitHash + worktreePath
   137→//  2. Single ref lookup to resolve the shadow branch
   138→//  3. Lists .entire/metadata/* entries in the shadow tree to extract session IDs
   139→//  4. Loads only those session state files
   140→//  5. Also loads any ACTIVE sessions from state files that might not have shadow
   141→//     branch data yet (they may not have had a SaveStep yet)
   142→//
   143→// This gives O(1) cost in git ref lookups regardless of total accumulated session
   144→// count, because only sessions on the current shadow branch are processed.
   145→// Step 2 scans all state files, but this is cheap (JSON parse + field checks only,
   146→// no git operations).
   147→func (s *ManualCommitStrategy) findSessionsFromShadowTree(ctx context.Context, repo *git.Repository, parentCommitHash, worktreePath string) ([]*SessionState, error) {
   148→	logCtx := logging.WithComponent(ctx, "checkpoint")
   149→
   150→	// Compute worktree ID and shadow branch name
   151→	worktreeID, err := paths.GetWorktreeID(worktreePath)
   152→	if err != nil {
   153→		return nil, fmt.Errorf("failed to get worktree ID: %w", err)
   154→	}
   155→
   156→	seen := make(map[string]bool)
   157→	var sessions []*SessionState
   158→
   159→	// Step 1: Find sessions from the shadow branch tree
   160→	if parentCommitHash != "" {
   161→		shadowBranch := checkpoint.ShadowBranchNameForCommit(parentCommitHash, worktreeID)
   162→		refName := plumbing.NewBranchReferenceName(shadowBranch)
   163→		if ref, refErr := repo.Reference(refName, true); refErr == nil {
   164→			if commitObj, cErr := repo.CommitObject(ref.Hash()); cErr == nil {
   165→				if tree, tErr := commitObj.Tree(); tErr == nil {
   166→					sessionIDs := extractSessionIDsFromTree(tree)
   167→					for _, sessionID := range sessionIDs {
   168→						if seen[sessionID] {
   169→							continue
   170→						}
   171→						state, loadErr := s.loadSessionState(ctx, sessionID)
   172→						if loadErr != nil || state == nil {
   173→							continue
   174→						}
   175→						if isFullyCondensedEnded(state) {
   176→							continue
   177→						}
   178→						seen[sessionID] = true
   179→						sessions = append(sessions, state)
   180→					}
   181→				}
   182→			}
   183→		}
   184→	}
   185→
   186→	// Step 2: Scan state files for sessions not yet in the shadow tree.
   187→	// This catches two cases:
   188→	//   a) ACTIVE sessions that haven't had SaveStep yet (no shadow branch data)
   189→	//   b) Non-active sessions with carry-forward files whose BaseCommit matches
   190→	//      the parent commit. Carry-forward shadow branches intentionally omit
   191→	//      metadata (to avoid sessionHasNewContent false positives), so these
   192→	//      sessions are invisible to the shadow tree scan above.
   193→	// This is cheap — just JSON parse + field checks, no ref lookups.
   194→	store, storeErr := s.getStateStore(ctx)
   195→	if storeErr != nil {
   196→		logging.Warn(logCtx, "findSessionsFromShadowTree: failed to get state store",
   197→			slog.String("error", storeErr.Error()))
   198→		return sessions, nil
   199→	}
   200→	allStates, listErr := store.List(ctx)
   201→	if listErr != nil {
   202→		logging.Warn(logCtx, "findSessionsFromShadowTree: failed to list session states",
   203→			slog.String("error", listErr.Error()))
   204→		return sessions, nil
   205→	}
   206→	for _, state := range allStates {
   207→		if seen[state.SessionID] {
   208→			continue
   209→		}
   210→		if state.WorktreePath != worktreePath {
   211→			continue
   212→		}
   213→		// Case (a): ACTIVE sessions without shadow branch data
   214→		if state.Phase.IsActive() {
   215→			seen[state.SessionID] = true
   216→			sessions = append(sessions, state)
   217→			continue
   218→		}
   219→		// Case (b): Non-active sessions with carry-forward files on this base commit.
   220→		// Carry-forward sessions track HEAD (BaseCommit is advanced on each
   221→		// non-overlapping commit via carryForwardToNewShadowBranch), so they
   222→		// always match the current parent. Carry-forward shadow branches
   223→		// intentionally omit metadata directories (to avoid sessionHasNewContent
   224→		// false positives), making these sessions invisible to Step 1.
   225→		if parentCommitHash != "" && state.BaseCommit == parentCommitHash && len(state.FilesTouched) > 0 {
   226→			if isFullyCondensedEnded(state) {
   227→				continue
   228→			}
   229→			seen[state.SessionID] = true
   230→			sessions = append(sessions, state)
   231→		}
   232→	}
   233→
   234→	return sessions, nil
   235→}
