   239→// files. IDLE sessions with FilesTouched are excluded — they may have content
   240→// that should be condensed on a future trailer-bearing commit.
   241→// Cheap — JSON parse + field checks only, no git ref lookups.
   242→func (s *ManualCommitStrategy) findActiveOrCarryForwardSessions(ctx context.Context, worktreePath string) ([]*SessionState, error) {
   243→	store, err := s.getStateStore(ctx)
   244→	if err != nil {
