} else {
	// Non-active carry-forward sessions must advance BaseCommit to the new HEAD
	// even when this commit does not overlap, so future PostCommit discovery
	// (findSessionsFromShadowTree Case b) can still find them via BaseCommit match.
	//
	// IDLE sessions also get a carry-forward shadow branch — the agent may resume,
	// and the branch makes sessionHasNewContent return true for future commits.
	//
	// ENDED sessions do NOT get a carry-forward shadow branch. The session is done;
	// creating a branch that no future commit may ever condense causes it to linger
	// indefinitely. BaseCommit advancement alone is sufficient for Case (b) discovery,
	// and if the session's files are eventually committed, the overlap check will
	// find them via the state file rather than the shadow branch.
	if !state.Phase.IsActive() && h.hasNew {
